import re
t=open(__import__('os').environ['RLM_SESSION_DIR']+'/../../sessions/'+__import__('os').environ['RLM_SESSION_DIR'].split('/')[-1]+'.jsonl').read().replace('\\n','\n')
G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]
print(sorted(G))
d=G['Demo pair 1 input']; o=G['Demo pair 1 output']
# hypothesis: block = 3x3; output color = any non-5 color in block (excluding 0?)
def f(g,s=3,bg=5):
    H=len(g)//s; W=len(g[0])//s
    out=[[0]*W for _ in range(H)]
    for bi in range(H):
        for bj in range(W):
            blk=[g[bi*s+i][bj*s+j] for i in range(s) for j in range(s)]
            c={v for v in blk if v!=bg and v!=0}
            if len(c)==1: out[bi][bj]=c.pop()
    return out
r=f(d)
print(r==o, r)

g=G['Test input']
multi=[]
for bi in range(7):
    for bj in range(7):
        c=[g[bi*3+i][bj*3+j] for i in range(3) for j in range(3) if g[bi*3+i][bj*3+j] not in (5,0)]
        if len(set(c))>1: multi.append((bi,bj,c))
print(multi)

